+// Generated by the pinned example translator. Do not edit.
+/// Checked addition; overflow returns None.
+///
+/// The typed input adapter refuses fractional and out-of-range inputs:
+/// ```compile_fail
+/// javascript_first_example::add(1.5, 0);
+/// ```
+/// ```compile_fail
+/// javascript_first_example::add(2147483648, 0);
+/// ```
+#[must_use]
+pub const fn add(a: i32, b: i32) -> Option<i32> { a.checked_add(b) }
+
+#[cfg(test)]
+mod tests {
+    use super::add;
+    #[test]
+    fn fixture_0() { assert_eq!(add(2, 3), Some(5)); }
+    #[test]
+    fn fixture_1() { assert_eq!(add(-5, 5), Some(0)); }
+    #[test]
+    fn fixture_2() { assert_eq!(add(-2147483648, 0), Some(-2147483648)); }
+    #[test]
+    fn fixture_3() { assert_eq!(add(2147483647, 0), Some(2147483647)); }
+    #[test]
+    fn fixture_6() { assert_eq!(add(2147483647, 1), None); }
+    #[test]
+    fn fixture_7() { assert_eq!(add(-2147483648, -1), None); }
+}

